@pytest.mark.parametrize("control", ["cancel", "revoke", "expire", "confirm-again"]) def test_pg_confirmation_control_transactions_are_linearized(env, monkeypatch, control): require_pg(env) value, session, rid, sent, worker, body = waiting(env) store, _, client, *_ = value before = authority(store) clock = [activation.now()] monkeypatch.setattr(activation, "now", lambda: clock[0]) actor = contextvars.ContextVar("activation_pg_actor", default=None) barrier = threading.Barrier(2) backend_ids = {} original = store.lock_project def project_lock(c, user, pid): name = actor.get() assert name in {"confirm", "control"} backend_ids[name] = c.execute(text("SELECT pg_backend_pid()")).scalar_one() barrier.wait(10) result = original(c, user, pid) if name == "control" and control == "expire": clock[0] = session["approval"]["expires_at"] return result monkeypatch.setattr(store, "lock_project", project_lock) def invoke(name): token = actor.set(name) try: if name == "confirm" or control == "confirm-again": return client.post(f"/api/runs/{rid}/confirm-natural-plan", json=body) if control == "cancel": return client.post(f"/api/runs/{rid}/commands", json={"command": "cancel", "version": body["expected_version"]}) if control == "revoke": return client.post(f"/api/natural-activations/{session['id']}/revoke", json={ "expected_version": session["version"], "expected_scope_fingerprint": session["scope_fingerprint"], "request_key": "race-revoke"}) return client.post(f"/api/natural-activations/{session['id']}/close-expired", json={}) finally: actor.reset(token) with ThreadPoolExecutor(max_workers=2) as pool: replies = list(pool.map(invoke, ("confirm", "control"))) monkeypatch.setattr(store, "lock_project", original) assert len(set(backend_ids.values())) == 2 confirmed = [r for r in rows(store, events) if r["kind"] == "NL_PLAN_CONFIRMED"] statuses = [r.status_code for r in replies] if control == "confirm-again": assert statuses == [200, 200] and replies[0].json() == replies[1].json() assert len(confirmed) == 1 assert worker.once() assert len(sent) == 1 and len(rows(store, operations)) == 1 assert client.get(f"/api/runs/{rid}").json()["result"]["receipts"][0]["data"]["sum"] == "19" else: if control == "cancel": assert sorted(statuses) == [200, 409] # A stale cancellation is rejected; explicit fresh cancel closes the winner. view = client.get(f"/api/runs/{rid}").json() if view["status"] == "QUEUED": cancelled = client.post(f"/api/runs/{rid}/commands", json={"command": "cancel", "version": view["version"]}) assert cancelled.status_code == 200, cancelled.text assert client.get(f"/api/runs/{rid}").json()["status"] == "CANCELLED" else: assert statuses[1] == 200 and statuses[0] in {200, 403} assert client.get(f"/api/natural-activations/{session['id']}").json()["status"] == ( "REVOKED" if control == "revoke" else "EXPIRED") assert len(confirmed) == (1 if statuses[0] == 200 else 0) worker.once() assert not rows(store, operations) and len(sent) == 1 assert client.get(f"/api/runs/{rid}").json()["result"] is None assert len(rows(store, attempts)) == len(rows(store, reservations)) == 1 > assert all(r["lease_until"] == 0 for r in rows(store, runs)) E assert False E + where False = all(<generator object test_pg_confirmation_control_transactions_are_linearized.<locals>.<genexpr> at 0x7ff698459ff0>)
